def multiply_int(a, b):
    # Handle negative numbers
    if a < 0 and b < 0:
        return -multiply_int(-a, -b)
    elif a < 0:
        return -multiply_int(-a, b)
    elif b < 0:
        return -multiply_int(a, -b)

    # Use repeated addition
    result = 0
    for _ in range(b):
        result += a
    return result
```

